import {useEffect,useMemo,useState} from 'react';
import {concepts,lessonSections,conceptGroups} from './concepts';
import {project,nodes,scaling,course,requestFlow} from './projects/all-media-downloader';
import {futureProjectSlots} from './projects';
import {incidents} from './projects/all-media-downloader/incidents';
import {questions} from './interview/questions';
import {loadState,saveState,setCompleted,toggleBookmark,percentFor,type LearningState} from './state';
import {gigabytesPerDay,littleLaw,mbps,percentile} from './simulations/math';
import {Icon,Badge,SectionTitle} from './components/ui';
import {knowledgeMap} from './data/knowledge-map';
import type {Lesson} from './types';

type Page='home'|'project'|'concepts'|'interview'|'incidents'|'simulators'|'rebuild'|'portfolio';

export default function App(){
  const [page,setPage]=useState<Page>('home');
  const [state,setState]=useState<LearningState>(()=>loadState());
  const [activeLesson,setActiveLesson]=useState<Lesson>(concepts[0]);
  const [selectedNode,setSelectedNode]=useState<string|null>(null);
  const [levelTab,setLevelTab]=useState<'simple'|'technical'|'interview'>('simple');
  const [toast,setToast]=useState('');
  const [theme,setTheme]=useState<'light'|'dark'>(()=>{
    const saved=window.localStorage.getItem('pl-theme');
    if(saved==='light'||saved==='dark') return saved;
    return window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';
  });
  useEffect(()=>saveState(state),[state]);
  useEffect(()=>{
    document.documentElement.dataset.theme=theme;
    document.documentElement.style.colorScheme=theme;
    window.localStorage.setItem('pl-theme',theme);
  },[theme]);
  function notify(text:string){setToast(text);window.setTimeout(()=>setToast(''),2300)}
  function openLesson(id:string){const l=concepts.find(x=>x.id===id);if(l){setActiveLesson(l);setPage('concepts');setLevelTab('simple');setSelectedNode(null)}}
  const nav:[Page,string,string][]=[['home','Overview','⌂'],['project','Projects','◇'],['concepts','Knowledge map','⌘'],['interview','Interview gym','◉'],['incidents','Incident lab','⚑'],['simulators','Simulations','⌁'],['rebuild','Final boss','✳'],['portfolio','Project story','↗']];
  return <div className="app-shell">
    <aside className="sidebar">
      <button className="brand" onClick={()=>setPage('home')}><span className="brand-mark">P<span>·</span>L</span><span>project<br/><b>learnings</b></span></button>
      <div className="sidebar-label">YOUR LEARNING SPACE</div>
      <nav>{nav.map(([id,label,icon])=><button key={id} className={`nav-item ${page===id?'active':''}`} onClick={()=>setPage(id)}><Icon>{icon}</Icon>{label}{id==='interview'&&<span className="nav-count">100</span>}</button>)}</nav>
      <div className="sidebar-bottom"><div className="mini-progress"><div className="sidebar-label">V1 CASE STUDY</div><strong>{percentFor(state,concepts.map(x=>x.id))}%</strong><div className="progress-track"><i style={{width:`${percentFor(state,concepts.map(x=>x.id))}%`}}/></div><small>{state.completed.filter(x=>x.startsWith('all-media-downloader:')).length} lessons completed</small></div><div className="privacy"><span className="green-dot"/>Saved on this device</div></div>
    </aside>
    <main className="main-area"><header className="topbar"><div className="breadcrumb">Learning platform <span>/</span> <b>{nav.find(x=>x[0]===page)?.[1]}</b></div><div className="top-right"><span className="online"><i/> Local learning mode</span><button className="theme-toggle" type="button" aria-label={`Switch to ${theme==='dark'?'light':'dark'} mode`} title={`Switch to ${theme==='dark'?'light':'dark'} mode`} onClick={()=>setTheme(theme==='dark'?'light':'dark')}><span aria-hidden="true">{theme==='dark'?'☀':'☾'}</span><b>{theme==='dark'?'Light':'Dark'}</b></button><button className="avatar" title="Your local progress">G</button></div></header>
      <div className="page-content">
        {page==='home'&&<Home state={state} setPage={setPage} openLesson={openLesson}/>}
        {page==='project'&&<ProjectPage state={state} onNode={(id)=>setSelectedNode(id)} openLesson={openLesson}/>}
        {page==='concepts'&&<ConceptPage state={state} setState={setState} lesson={activeLesson} setLesson={setActiveLesson} tab={levelTab} setTab={setLevelTab} notify={notify}/>}
        {page==='interview'&&<InterviewPage state={state} setState={setState}/>}
        {page==='incidents'&&<IncidentPage/>}
        {page==='simulators'&&<Simulators/>}
        {page==='rebuild'&&<RebuildBoss/>}
        {page==='portfolio'&&<Portfolio/>}
      </div>
      <footer className="footer">A learning platform built from real projects <span>·</span> Progress stays in this browser</footer>
    </main>
    {selectedNode&&<NodeDrawer id={selectedNode} close={()=>setSelectedNode(null)} openLesson={openLesson}/>}
    {toast&&<div className="toast" role="status">{toast}</div>}
  </div>;
}

function Home({state,setPage,openLesson}:{state:LearningState;setPage:(p:Page)=>void;openLesson:(s:string)=>void}){
  const cats=[['Concurrency',['asyncio','threads','process-pool','queue','backpressure','semaphore','singleflight-cache']],['Linux memory',['memory-virtual','swap-psi']],['Networking',['tcp-http','rate-limiting']],['System design',['system-design','scale-triggers','distributed-systems','technology-judgment']],['Databases',['sqlite-wal','durability-idempotency']],['SRE',['cgroups-systemd','observability','experiments-percentiles']]] as const;
  const total=concepts.length,done=state.completed.filter(x=>x.startsWith('all-media-downloader:')).length;
  const quizStats=Object.values(state.quiz).reduce((a,x)=>({correct:a.correct+x.correct,total:a.total+x.total}),{correct:0,total:0});
  const reviewCount=Object.values(state.flashcards).filter(x=>x==='review').length;
  const weakest=Object.entries(state.confidence).sort((a,b)=>a[1]-b[1]).slice(0,3);
  return <>
    <section className="hero"><div className="hero-copy"><div className="eyebrow light">YOUR PERSONAL ENGINEERING UNIVERSITY</div><h1>Project<br/><em>Learnings</em></h1><p className="hero-sub">Learn software engineering through systems you actually built.</p><div className="hero-actions"><button className="button light-button" onClick={()=>setPage('project')}>Explore the system <span>↗</span></button><button className="text-button light-text" onClick={()=>setPage('concepts')}>Browse by concept <span>→</span></button></div><div className="hero-note"><span className="green-dot"/> From real code to production reasoning</div></div><div className="hero-art"><div className="orb orb-a"/><div className="orb orb-b"/><div className="flow-chip chip-one">CODE <span>→</span> SYSTEMS</div><div className="flow-chip chip-two">WHY <span>→</span> EVIDENCE</div><div className="flow-chip chip-three">CS <span>→</span> PRODUCTION</div><div className="hero-ring ring-one"/><div className="hero-ring ring-two"/><div className="hero-center">P<span>·</span>L</div></div><div className="hero-index">LEARNING PATH 01 / 24</div></section>
    <div className="section-heading-row"><SectionTitle eyebrow="START HERE" title="Choose your way in" description="One real project, connected to concepts and interview reasoning."/><div className="inline-progress"><span>{done}/{total}</span><small>lessons complete</small></div></div>
    <div className="entry-grid"><button className="entry-card project-entry" onClick={()=>setPage('project')}><div className="entry-top"><span className="entry-icon">◈</span><span className="arrow-round">↗</span></div><div className="eyebrow">BY PROJECT · FIRST CASE STUDY</div><h2>All Media<br/>Downloader</h2><p>Backend · Concurrency · Linux · DevOps · System design</p><div className="entry-bottom"><span>Single-node production Telegram backend</span><b>Explore case study →</b></div></button><button className="entry-card concepts-entry" onClick={()=>setPage('concepts')}><div className="entry-top"><span className="entry-icon">⌘</span><span className="arrow-round">↗</span></div><div className="eyebrow">BY CONCEPT · REUSABLE KNOWLEDGE</div><h2>Knowledge<br/>Map</h2><p>Connect familiar CS foundations to production behavior.</p><div className="entry-bottom"><span>{concepts.length} shared concepts</span><b>Open the map →</b></div></button><button className="entry-card interview-entry" onClick={()=>setPage('interview')}><div className="entry-top"><span className="entry-icon">◎</span><span className="arrow-round">↗</span></div><div className="eyebrow">BY INTERVIEW TOPIC · 5 LEVELS</div><h2>Interview<br/>Gym</h2><p>Practice explaining what, why, evidence and trade-offs.</p><div className="entry-bottom"><span>{questions.length} progressive prompts</span><b>Start practicing →</b></div></button></div>
    <div className="future-project-strip"><div><div className="eyebrow">BUILT TO GROW</div><b>Future projects plug into the same knowledge graph.</b></div>{futureProjectSlots.map(x=><button key={x.id} onClick={()=>setPage('project')}><span>＋</span>{x.title}<small>{x.subtitle}</small></button>)}</div>
    <section className="dashboard-grid"><div className="panel progress-panel"><div className="panel-head"><div><div className="eyebrow">YOUR PROGRESS</div><h2>Learning, not guessing</h2></div><button className="subtle-button" onClick={()=>setPage('concepts')}>Continue learning →</button></div><p className="muted">Percentages show lessons completed, not a score for your ability.</p><div className="skill-list">{cats.map(([name,ids])=>{const pct=percentFor(state,ids as unknown as string[]);return <button className="skill-row" key={name} onClick={()=>{const l=concepts.find(c=>ids.includes(c.id as never));if(l)openLesson(l.id)}}><span className="skill-name">{name}</span><div className="progress-track"><i style={{width:`${pct}%`}}/></div><b>{pct}%</b></button>})}</div><div className="progress-foot"><span>{done} of {total} lessons marked complete</span><button onClick={()=>openLesson('asyncio')}>Pick up where you left off →</button></div></div><div className="panel knowledge-panel"><div className="eyebrow">THE KNOWLEDGE MAP</div><h2>Build from<br/>what you know.</h2><div className="knowledge-stack">{knowledgeMap.map((x,i)=><button key={x.label} onClick={()=>openLesson(x.concept)}><span>{String(i+1).padStart(2,'0')}</span>{x.label}<b>→</b></button>)}</div><div className="knowledge-foot">Academic foundations <span>↓</span> production judgment</div></div></section>
    <section className="learning-signals"><div><span>QUIZ ACCURACY</span><b>{quizStats.total?Math.round(quizStats.correct/quizStats.total*100):0}%</b><small>{quizStats.correct} correct · {quizStats.total} attempts</small></div><div><span>FLASHCARDS TO REVIEW</span><b>{reviewCount}</b><small>Marked “Review” on this device</small></div><div><span>INTERVIEW PRACTICE</span><b>{Object.keys(state.confidence).length} topics</b><small>{weakest.length?`Weak focus: ${weakest.map(([k])=>k).join(', ')}`:'Self-ratings will highlight weak topics'}</small></div></section>
    <section className="bottom-cta"><div><div className="eyebrow">THE FIRST PROJECT</div><h2>Follow one request<br/>through the whole system.</h2><p>Start with the architecture map. Every component opens a code-backed lesson.</p></div><button className="button dark-button" onClick={()=>setPage('project')}>Open architecture map <span>↗</span></button></section>
  </>;
}

function ProjectPage({state,onNode,openLesson}:{state:LearningState;onNode:(id:string)=>void;openLesson:(id:string)=>void}){
  const [step,setStep]=useState(-1);const [tab,setTab]=useState<'map'|'lifecycle'|'course'|'evidence'>('map');
  const mainNodes=['user','telegram-api','handlers','validation','metadata','queue','executor','ytdlp','disk','uploadgate','stream','delivery'];
  const support=['deno','ffmpeg','sqlite','json','warp','systemd','cgroups','health','kuma'];
  const order=requestFlow;
  const stepNodeIds=['user','telegram-api','handlers','validation','metadata','metadata','queue','executor','ytdlp','deno','disk','uploadgate','stream','delivery','user'];
  const flowNodes=mainNodes.map(id=>nodes.find(n=>n.id===id)!);
  return <>
    <div className="project-hero"><div><div className="eyebrow">PROJECT 01 · PRODUCTION CASE STUDY</div><h1>All Media<br/><em>Downloader</em></h1><p>{project.oneLiner}</p><div className="badges">{project.badges.map(x=><Badge key={x}>{x}</Badge>)}</div></div><div className="project-stamp"><span>APPLICATION BASELINE</span><b>v1.0.0</b><code>830f351</code><small>Docs freeze 374acfd<br/>describes this baseline</small></div></div>
    <div className="tabbar">{[['map','Architecture map'],['lifecycle','Follow a request'],['course','Learning roadmap'],['evidence','Evidence & constraints']].map(([id,label])=><button className={tab===id?'selected':''} key={id} onClick={()=>setTab(id as typeof tab)}>{label}</button>)}</div>
    {tab==='map'&&<><div className="map-intro"><div><div className="eyebrow">CLICK ANY COMPONENT</div><h2>One bot. Many boundaries.</h2><p>Each node opens its role, CS connection, code location, resource cost and failure mode.</p></div><div className="map-legend"><span><i className="legend-app"/>App</span><span><i className="legend-external"/>External</span><span><i className="legend-ops"/>Operations</span></div></div><div className="architecture-board"><div className="main-flow">{flowNodes.map((n,i)=><div className="flow-item" key={n.id}><button className={`arch-node ${n.kind}`} onClick={()=>onNode(n.id)}><span className="node-num">{String(i+1).padStart(2,'0')}</span><b>{n.label}</b><small>{n.subtitle}</small><span className="node-open">↗</span></button>{i<flowNodes.length-1&&<div className="flow-arrow"><span>↓</span></div>}</div>)}</div><div className="support-panel"><div className="eyebrow">SUPPORTING SYSTEMS · CLICK TO EXPLORE</div><div className="support-grid">{support.map(id=>{const n=nodes.find(n=>n.id===id)!;return <button key={id} onClick={()=>onNode(id)} className={`support-node ${n.kind}`}><span>{n.kind==='ops'?'⌘':n.kind==='storage'?'▤':n.kind==='dependency'?'↗':'◇'}</span><b>{n.label}</b><small>{n.subtitle}</small><i>↗</i></button>})}</div></div><div className="board-caption"><span>CODE BASELINE <b>830f351</b></span><span>DOCS-ONLY FREEZE <b>374acfd</b></span><span>Project-specific evidence is labeled [C] or [M]</span></div></div><div className="map-footnote"><b>Production topology:</b> bot under host systemd; Kuma and bgutil in containers; WARP is a host service when configured. The local Compose bot is a separate supported topology.</div></>}
    {tab==='lifecycle'&&<div className="panel lifecycle-panel"><div className="panel-head"><div><div className="eyebrow">INTERACTIVE REQUEST TRACE</div><h2>Follow one request</h2><p className="muted">Advance the same job across each boundary. Tap a step to open its lesson.</p></div><button className="button green-button" onClick={()=>setStep(step>=order.length-1?-1:step+1)}>{step<0?'Start the request':step>=order.length-1?'Start again':'Next step →'}</button></div><div className="request-track">{order.map((label,i)=>{const n=nodes.find(x=>x.id===stepNodeIds[i]);return <div className={`request-step ${i<=step?'reached':''} ${i===step?'current':''}`} key={`${label}-${i}`}><button onClick={()=>n&&onNode(n.id)}><span>{String(i+1).padStart(2,'0')}</span><b>{label}</b><small>{i===step?'Now processing':i<step?'Complete':i===step+1?'Next boundary':'Waiting'}</small></button>{i<order.length-1&&<i className={i<step?'done':''}/>}</div>})}</div><div className="callout"><b>Boundary check</b><span>A user-facing success depends on external services and local resource limits, not only handler code. Timeouts bound how long this process waits; they cannot undo a remote side effect.</span></div></div>}
    {tab==='course'&&<><SectionTitle eyebrow="24 LEVELS · BUILD IN ORDER" title="Learning roadmap" description="Start with the CS you know, then assemble it into production and system-design reasoning."/><div className="roadmap">{course.map(c=><div className="roadmap-level" key={c.level}><div className="level-number">{String(c.level).padStart(2,'0')}</div><div className="level-body"><div className="eyebrow">LEVEL {c.level}</div><h3>{c.title}</h3><p>{c.description}</p><div className="concept-chips">{c.conceptIds.map(id=>{const l=concepts.find(c=>c.id===id)!;return <button key={id} onClick={()=>openLesson(id)}>{l.title} <span>↗</span></button>})}</div></div><div className="level-status">{c.conceptIds.every(id=>state.completed.includes(`all-media-downloader:${id}`))?<span className="status-done">Complete ✓</span>:<span>Start level →</span>}</div></div>)}</div></>}
    {tab==='evidence'&&<><SectionTitle eyebrow="SOURCE PROJECT SNAPSHOT" title="Facts before conclusions" description="The code and tests describe current behavior. Historical measurements are labeled and their limits stay visible."/><div className="evidence-grid">{project.constraints.map(([label,desc])=><div className="evidence-card" key={label}><div className="eyebrow">{label}</div><p>{desc}</p></div>)}</div><div className="panel"><div className="panel-head"><div><div className="eyebrow">HISTORICAL 24-HOUR COMPARISON</div><h2>Observed, not attributed</h2></div><Badge>[M] · baseline vs trial</Badge></div><div className="metric-table">{project.metrics.map(m=><div className="metric-row" key={m.name}><b>{m.name}</b><span>{m.baseline}</span><i>→</i><span>{m.trial}</span><small>{m.evidence}</small></div>)}</div><p className="muted">Multiple settings changed and CPU steal changed. This comparison does not prove a single change caused the differences. Raw measurement files are not included in this learning repository; see source project docs for the summarized historical evidence.</p></div></>}
  </>;
}

function NodeDrawer({id,close,openLesson}:{id:string;close:()=>void;openLesson:(id:string)=>void}){
  const node=nodes.find(n=>n.id===id)!;const lesson=concepts.find(c=>c.id===node.lesson)!;
  return <div className="drawer-backdrop" onClick={close}><aside className="node-drawer" onClick={e=>e.stopPropagation()}><button className="close-button" onClick={close}>×</button><div className="eyebrow">ARCHITECTURE COMPONENT · {node.kind}</div><h2>{node.label}</h2><p className="muted">{node.subtitle}</p><div className="drawer-section"><h3>What is this?</h3><p>{lesson.technical}</p></div><div className="drawer-section"><h3>OS / CN / DBMS connection</h3><p>{lesson.cs}</p></div><div className="drawer-pair"><div><small>CODE LOCATION</small><b>{lesson.location}</b></div><div><small>RESOURCE CONSUMED</small><b>{lesson.resource}</b></div><div><small>WHAT PROTECTS IT?</small><b>{lesson.protection}</b></div><div><small>FAILURE MODE</small><b>{lesson.failure}</b></div></div><div className="drawer-section"><h3>Scale problem</h3><p>{lesson.scale}</p></div><div className="drawer-section interview-quote"><h3>Interview question</h3><p>{lesson.followup}</p></div><button className="button green-button full-button" onClick={()=>openLesson(lesson.id)}>Open complete lesson →</button></aside></div>;
}

function ConceptPage({state,setState,lesson,setLesson,tab,setTab,notify}:{state:LearningState;setState:(x:LearningState)=>void;lesson:Lesson;setLesson:(x:Lesson)=>void;tab:'simple'|'technical'|'interview';setTab:(x:'simple'|'technical'|'interview')=>void;notify:(s:string)=>void}){
  const [filter,setFilter]=useState('All');const [query,setQuery]=useState('');const [quiz,setQuiz]=useState(false);const [answered,setAnswered]=useState<number|null>(null);const [qIndex,setQIndex]=useState(0);
  const groups=['All',...conceptGroups];const visible=concepts.filter(c=>(filter==='All'||c.group===filter)&&c.title.toLowerCase().includes(query.toLowerCase()));
  const isDone=state.completed.includes(`all-media-downloader:${lesson.id}`);const isBookmarked=state.bookmarks.includes(lesson.id);
  const quizItems=[
    {q:'Seven people request the same uncached URL at nearly the same time. What should happen?',a:['Seven extractions run concurrently','One extraction runs and the other callers join','A SQLite transaction serializes seven downloads'],correct:1,why:'The in-flight future coalesces current work. The cache helps future requests after a result exists.'},
    {q:'Two Telegram uploads already use both upload slots. Should a completed third job keep its download slot while waiting?',a:['Yes, to preserve ordering','No; release download capacity and wait at UploadGate','Start a second bot process'],correct:1,why:'Download and upload are separate stages; waiting for Telegram should not occupy a scarce download slot.'},
    {q:'A coroutine times out while its ThreadPoolExecutor function is still blocked. What is true?',a:['The worker thread is forcibly killed','The await ended, but the callable may keep running','The operating system rolls back its network request'],correct:1,why:'Cancelling a Future does not safely terminate an already-running arbitrary thread.'},
    {q:'A host has nonzero swap used but low swap-in, low PSI and stable latency. Is that automatically an incident?',a:['Yes, any swap use is failure','No; occupancy alone is not active pressure','Disable swap immediately'],correct:1,why:'Swap occupancy can be a stock of inactive pages. Correlate active paging, PSI and user latency.'},
    {q:'What is the best reason to add Redis/Celery?',a:['A resume needs more technologies','Measured need for durable cross-process work that local queue cannot meet','A traffic multiplier is large'],correct:1,why:'Name the job durability, throughput or availability requirement and its operational trade-off.'},
  ];
  const submitQuiz=(ans:number)=>{setAnswered(ans);const key=lesson.id;const prev=state.quiz[key]||{correct:0,total:0};setState({...state,quiz:{...state.quiz,[key]:{correct:prev.correct+(ans===quizItems[qIndex].correct?1:0),total:prev.total+1}}})};
  return <div className="concept-layout"><aside className="concept-sidebar"><div className="eyebrow">SHARED CONCEPT LIBRARY</div><input className="search-input" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Find a concept…"/><select value={filter} onChange={e=>setFilter(e.target.value)} aria-label="Filter concepts by area">{groups.map(g=><option key={g}>{g}</option>)}</select><div className="concept-list">{visible.map(c=><button className={lesson.id===c.id?'current':''} key={c.id} onClick={()=>{setLesson(c);setQuiz(false);setAnswered(null)}}><span className="concept-dot"/>{c.title}{state.completed.includes(`all-media-downloader:${c.id}`)&&<b>✓</b>}</button>)}</div><div className="library-note">Shared lessons are reused by future project examples.</div></aside><section className="lesson-area"><div className="lesson-head"><div className="eyebrow">{lesson.group.toUpperCase()} · LEVEL {lesson.level}</div><div className="lesson-head-row"><div><h1>{lesson.title}</h1><p>{lesson.summary}</p></div><button className={`bookmark ${isBookmarked?'saved':''}`} onClick={()=>setState(toggleBookmark(state,lesson.id))}>{isBookmarked?'★ Saved':'☆ Save'}</button></div><div className="lesson-controls"><div className="segmented">{(['simple','technical','interview'] as const).map(x=><button key={x} className={tab===x?'on':''} onClick={()=>setTab(x)}>{x==='simple'?'Simple':x==='technical'?'Technical':'Interview'}</button>)}</div><button className="subtle-button" onClick={()=>isDone?notify('Already marked complete'):setState(setCompleted(state,lesson.id))}>{isDone?'✓ Lesson complete':'Mark complete'}</button></div></div>
      <div className="lesson-highlight"><span className="highlight-icon">✳</span><div><small>{tab==='simple'?'THE INTUITION':tab==='technical'?'THE PRECISE DEFINITION':'SAY IT IN AN INTERVIEW'}</small><p>{tab==='simple'?lesson.intuition:tab==='technical'?lesson.technical:lesson.interview}</p></div></div>
      <ConceptVisualization lesson={lesson}/>
      <div className="lesson-grid">{lessonSections.map(([title,key],i)=><article className={`lesson-block ${i===3?'source-block':''}`} key={key}><div className="lesson-block-head"><span>{String(i+1).padStart(2,'0')}</span><h3>{title}</h3></div><p>{String(lesson[key])}</p>{i===3&&<><div className="code-location"><span>⌘</span><code>{lesson.location}</code></div><pre className="code-snippet"><code>{lesson.snippet}</code><button aria-label="Copy code" onClick={()=>navigator.clipboard?.writeText(lesson.snippet)}>⧉</button></pre><div className="resource-line"><span>RESOURCE</span><b>{lesson.resource}</b><span>PROTECTION</span><b>{lesson.protection}</b></div></>}</article>)}</div>
      <div className="lesson-source-note"><Badge>[C] Code-derived</Badge><span>Source project: {project.appBaseline}. Historical evidence is marked [M]; where the repository lacks per-job attribution, it says “Not measured.”</span></div>
      <div className="flashcard-row"><div><div className="eyebrow">FLASHCARD</div><h3>One thing to remember</h3><p>{lesson.intuition}</p></div><div className="flashcard-actions"><button onClick={()=>setState({...state,flashcards:{...state.flashcards,[lesson.id]:'review'}})}>↻ Review</button><button onClick={()=>setState({...state,flashcards:{...state.flashcards,[lesson.id]:'know'}})}>✓ Know it</button></div></div>
      <div className="quiz-panel"><div className="panel-head"><div><div className="eyebrow">SCENARIO CHECK</div><h2>Can you apply it?</h2></div>{state.quiz[lesson.id]&&<Badge>{state.quiz[lesson.id].correct}/{state.quiz[lesson.id].total} correct</Badge>}</div>{!quiz?<button className="button dark-button" onClick={()=>{setQuiz(true);setAnswered(null)}}>Start 5-question scenario quiz →</button>:<><div className="quiz-count">QUESTION {qIndex+1} / {quizItems.length}</div><h3>{quizItems[qIndex].q}</h3><div className="quiz-options">{quizItems[qIndex].a.map((a,i)=><button key={a} disabled={answered!==null} className={answered===i?(i===quizItems[qIndex].correct?'correct':'incorrect'):''} onClick={()=>submitQuiz(i)}>{a}</button>)}</div>{answered!==null&&<div className="quiz-feedback"><b>{answered===quizItems[qIndex].correct?'Good reasoning.':'Revisit the distinction.'}</b> {quizItems[qIndex].why}<button onClick={()=>{setQIndex((qIndex+1)%quizItems.length);setAnswered(null)}}>{qIndex===quizItems.length-1?'Next round':'Next question'} →</button></div>}</>}</div>
    </section></div>;
}

function ConceptVisualization({lesson}:{lesson:Lesson}){
  if(lesson.id==='singleflight-cache')return <div className="concept-viz"><div className="eyebrow">SEVEN SIMULTANEOUS CACHE MISSES · CONCEPTUAL</div><div className="flight-layout"><div className="caller-stack">{Array.from({length:7},(_,i)=><span key={i}>Caller {i+1} · same URL</span>)}</div><div className="flight-lines"><i/><i/><i/><i/><i/><i/><i/></div><div className="extractor-box"><b>1 extraction</b><small>leader work</small></div><div className="waiter-note">6 callers join the in-flight result</div></div><div className="contrast-row"><div><b>Cache only</b><span>7 misses can start 7 extractions before the first result is cached.</span></div><div><b>Cache + single-flight</b><span>One current extraction; later requests may hit the completed TTL cache.</span></div></div></div>;
  if(lesson.id==='streaming')return <div className="concept-viz"><div className="eyebrow">UPLOAD PATH · PYTHON HEAP VS DISK</div><div className="stream-compare"><div className="stream-card old"><small>OLD PATTERN · WHOLE-FILE BUFFER</small><b>49 MB file</b><span>→ `bytes` in Python memory → HTTP request</span><div className="memory-gauge"><i style={{width:'92%'}}/></div><em>large avoidable anonymous allocation</em></div><div className="stream-card new"><small>V1 · STREAM OPEN FILE</small><b>disk → small chunk → socket</b><span>read next chunk as HTTP client sends</span><div className="memory-gauge"><i style={{width:'16%'}}/></div><em>bounded application buffering; page cache still exists</em></div></div><p className="viz-caveat">The gauge is schematic, not a measured allocation or benchmark. Actual memory depends on HTTP buffers, kernel page cache and concurrency.</p></div>;
  if(lesson.id==='cpu-steal')return <div className="concept-viz"><div className="eyebrow">VIRTUALIZED CPU SCHEDULING</div><div className="hypervisor-stack"><div>Physical host CPU</div><i>↓ hypervisor schedules guests</i><div className="guest-row"><b>Other guest gets time</b><b className="ours">Our VM gets a turn</b></div><i>↓ guest scheduler</i><div>Bot threads and child processes</div></div><p className="viz-caveat">More bot workers compete inside the VM. They cannot reclaim time the hypervisor did not schedule to the VM.</p></div>;
  if(lesson.id==='durability-idempotency'||lesson.id==='distributed-systems')return <div className="concept-viz"><div className="eyebrow">LOCAL STATE VS REMOTE SIDE EFFECT</div><div className="state-compare"><div><small>CURRENT · SINGLE HOST</small><b>bot process</b><span>in-memory queue</span><span>SQLite history on local disk</span><span>best-effort interruption marker</span></div><div><small>FUTURE · MULTIPLE WORKERS</small><b>queue + worker fleet</b><span>durable job ownership</span><span>shared database/object storage</span><span>dedupe + lease/recovery rules</span></div></div><p className="viz-caveat">The second diagram is a design exercise, not implemented v1 architecture.</p></div>;
  if(lesson.id==='sqlite-wal')return <div className="concept-viz"><div className="eyebrow">WRITE-AHEAD LOG · SIMPLIFIED</div><div className="wal-flow"><span>Reader A sees stable snapshot</span><b>Database file</b><b className="wal">WAL append ← Writer</b><span>Checkpoint later merges pages</span></div><p className="viz-caveat">WAL supports local readers while writes append; SQLite still serializes writers. It does not make download jobs durable.</p></div>;
  return null;
}

function InterviewPage({state,setState}:{state:LearningState;setState:(s:LearningState)=>void}){
  const [mode,setMode]=useState<'bank'|'mock'|'cards'>('bank');const [level,setLevel]=useState('All');const [topic,setTopic]=useState('All');const [idx,setIdx]=useState(0);const [show,setShow]=useState(false);const [search,setSearch]=useState('');
  const topics=['All',...Array.from(new Set(questions.map(q=>q.topic)))];
  const list=questions.filter(q=>(level==='All'||q.level===level)&&(topic==='All'||q.topic===topic)&&q.question.toLowerCase().includes(search.toLowerCase()));
  const current=list[idx%Math.max(1,list.length)];
  const weakest=useMemo(()=>{const vals=Object.entries(state.confidence);return vals.sort((a,b)=>a[1]-b[1])[0]?.[0]},[state.confidence]);
  const mockList=useMemo(()=>{const low=weakest?questions.filter(q=>q.topic===weakest):[];return low.length?low:questions},[weakest]);
  return <><SectionTitle eyebrow="100 QUESTIONS · FIVE LEVELS" title="Interview gym" description="Practice a topic from fundamentals through production diagnosis and system evolution. Self-grade honestly; weak topics are prioritised locally."/><div className="tabbar interview-tabs">{[['bank','Question bank'],['mock','Mock interview'],['cards','Flashcards']].map(([id,t])=><button key={id} className={mode===id?'selected':''} onClick={()=>{setMode(id as typeof mode);setIdx(0);setShow(false)}}>{t}</button>)}</div>
    {mode==='bank'&&<><div className="filterbar"><input className="search-input" value={search} onChange={e=>{setSearch(e.target.value);setIdx(0)}} placeholder="Search questions…"/><select value={level} onChange={e=>{setLevel(e.target.value);setIdx(0)}}><option>All</option>{['A','B','C','D','E'].map(l=><option key={l} value={l}>Level {l}</option>)}</select><select value={topic} onChange={e=>{setTopic(e.target.value);setIdx(0)}}>{topics.map(t=><option key={t}>{t}</option>)}</select><Badge>{questions.length} total · {list.length} shown</Badge></div>{current&&<QuestionCard key={current.id} q={current} show={show} setShow={setShow}/>}<div className="question-nav"><button onClick={()=>setIdx(Math.max(0,idx-1))}>← Previous</button><span>{idx+1} / {list.length}</span><button onClick={()=>{setIdx((idx+1)%Math.max(1,list.length));setShow(false)}}>Next question →</button></div></>}
    {mode==='mock'&&current&&<div className="mock-card"><div className="mock-top"><Badge>MOCK INTERVIEW</Badge><span>{weakest?`Weak topic focus: ${weakest}`:'One question at a time'}</span></div><div className="eyebrow">LEVEL {mockList[idx%mockList.length].level} · {mockList[idx%mockList.length].topic}</div><h2>{mockList[idx%mockList.length].question}</h2><button className="subtle-button" onClick={()=>setShow(!show)}>{show?'Hide answer':'Reveal answer'}</button>{show&&<QuestionCard q={mockList[idx%mockList.length]} show setShow={setShow} compact/>}<div className="confidence"><span>How confident were you?</span>{[['Don’t know',1],['Weak',2],['Okay',3],['Strong',4]].map(([label,n])=><button key={String(n)} onClick={()=>{const q=mockList[idx%mockList.length];setState({...state,confidence:{...state.confidence,[q.topic]:Number(n)}});setIdx((idx+1)%mockList.length);setShow(false)}}>{label}</button>)}</div></div>}
    {mode==='cards'&&<div className="cards-page"><div className="panel-head"><div><div className="eyebrow">LOCAL FLASHCARDS</div><h2>Retrieve, then review</h2></div><Badge>{Object.keys(state.flashcards).length} tracked</Badge></div><div className="flashcard-grid">{concepts.map(c=><div className="flashcard" key={c.id}><div className="eyebrow">{c.group}</div><h3>{c.title}</h3><p>{c.intuition}</p><div><button className={state.flashcards[c.id]==='know'?'picked':''} onClick={()=>setState({...state,flashcards:{...state.flashcards,[c.id]:'know'}})}>✓ Know</button><button className={state.flashcards[c.id]==='review'?'picked':''} onClick={()=>setState({...state,flashcards:{...state.flashcards,[c.id]:'review'}})}>↻ Review</button></div></div>)}</div></div>}
  </>;
}
function QuestionCard({q,show,setShow,compact=false}:{q:(typeof questions)[number];show:boolean;setShow:(s:boolean)=>void;compact?:boolean}){return <article className={`question-card ${compact?'compact':''}`}><div className="question-meta"><Badge>LEVEL {q.level}</Badge><span>{q.topic}</span></div><h2>{q.question}</h2><div className="hint-box"><b>Hint</b><p>{q.hint}</p></div>{show?<div className="answer-grid">{[['Concise answer',q.concise],['Deep answer',q.deep],['Project example',q.project],['Likely follow-up',q.followup],['Weak answer',q.weak],['Strong answer',q.strong]].map(([k,v])=><div key={k}><div className="eyebrow">{k}</div><p>{v}</p></div>)}</div>:<button className="button dark-button" onClick={()=>setShow(true)}>Reveal answer rubric →</button>}</article>}

function IncidentPage(){
  const [active,setActive]=useState(incidents[0].id);const [choice,setChoice]=useState<number|null>(null);const [revealed,setRevealed]=useState(false);const item=incidents.find(x=>x.id===active)!;
  function selectIncident(id:string){setActive(id);setChoice(null);setRevealed(false)}
  return <><SectionTitle eyebrow="INCIDENT LEARNING · ANSWERS HIDDEN" title="Incident lab" description="Read the symptoms and evidence first. Pick an investigation path before seeing the diagnosis; several scenarios have uncertainty or limited attribution."/><div className="incident-layout"><aside className="incident-list">{incidents.map(i=><button key={i.id} className={active===i.id?'active':''} onClick={()=>selectIncident(i.id)}><span>⚑</span><b>{i.title}</b><small>{i.evidenceTag}</small></button>)}</aside><article className="incident-detail"><div className="incident-banner"><div className="eyebrow">CASE FILE · {item.evidenceTag}</div><h2>{item.title}</h2><p>{item.symptom}</p></div><div className="incident-columns"><div><h3>Evidence available</h3>{item.evidence.map(x=><p className="evidence-point" key={x}><span>↳</span>{x}</p>)}</div><div><h3>Code hints</h3>{item.hints.map(x=><p className="evidence-point" key={x}><span>↳</span>{x}</p>)}</div></div><div className="investigate"><div className="eyebrow">WHAT WOULD YOU INVESTIGATE FIRST?</div>{item.options.map((o,i)=><button key={o} className={choice===i?'chosen':''} onClick={()=>{setChoice(i);setRevealed(false)}}><span>{String.fromCharCode(65+i)}</span>{o}</button>)}{choice!==null&&<button className="button green-button" onClick={()=>setRevealed(true)}>Commit to this hypothesis →</button>}</div>{revealed&&<div className="diagnosis"><div className="eyebrow">THE POSTMORTEM</div><h3>Actual diagnosis</h3><p>{item.diagnosis}</p><div className="diagnosis-grid">{[['Fix',item.fix],['Test',item.test],['Production verification',item.verify],['Lesson',item.lesson]].map(([k,v])=><div key={k}><small>{k}</small><p>{v}</p></div>)}</div><Badge>{item.evidenceTag}</Badge></div>}</article></div></>;
}

function Simulators(){const [which,setWhich]=useState('Concurrency timeline');return <><SectionTitle eyebrow="WHAT-IF LAB · SIMULATED, NOT A BENCHMARK" title="Make the system move" description="Change an input and see the relationship. The numbers below are educational estimates unless labeled [M]."/><div className="sim-nav">{['Concurrency timeline','Download queue','UploadGate','Memory & swap','Percentiles','Little’s Law','Capacity planning','Bottleneck quiz','Scale ladder'].map(x=><button className={which===x?'on':''} onClick={()=>setWhich(x)} key={x}>{x}</button>)}</div>{which==='Concurrency timeline'&&<ConcurrencySim/>}{which==='Download queue'&&<QueueSim/>}{which==='UploadGate'&&<UploadSim/>}{which==='Memory & swap'&&<MemorySim/>}{which==='Percentiles'&&<PercentileSim/>}{which==='Little’s Law'&&<LittleLawSim/>}{which==='Capacity planning'&&<CapacitySim/>}{which==='Bottleneck quiz'&&<BottleneckSim/>}{which==='Scale ladder'&&<ScaleSim/>}</>}

function ConcurrencySim(){const [mode,setMode]=useState('Async I/O');const [run,setRun]=useState(false);return <div className="panel sim-panel"><div className="panel-head"><div><div className="eyebrow">EVENT LOOP · OS THREADS · PROCESSES</div><h2>Concurrency timeline</h2><p className="muted">Same network-wait workload; see how the coordinator uses waiting time.</p></div><select value={mode} onChange={e=>{setMode(e.target.value);setRun(false)}}><option>Async I/O</option><option>Blocking synchronous</option><option>ThreadPoolExecutor</option><option>ProcessPoolExecutor</option></select></div><button className="button green-button" onClick={()=>setRun(!run)}>{run?'Reset timeline':'Run timeline →'}</button><div className="timeline">{['Request A','Request B','Request C'].map((x,i)=><div className="timeline-row" key={x}><b>{x}</b><div className="timeline-lane"><span className={run?`work ${mode==='Blocking synchronous'&&i>0?'delayed':''}`:''}>{run?(mode==='Blocking synchronous'&&i>0?'WAITING TURN':'WORK → WAIT → RESULT'):'READY'}</span>{mode==='Async I/O'&&run&&<small>event loop handles another task at await</small>}</div></div>)}</div><div className="callout"><b>Key distinction</b><span>Async can overlap waits; it does not execute CPU-heavy Python on multiple cores. Threads are OS scheduled and share memory; process-pool tasks need serialization and separate memory. These lanes are a simplified [E] teaching model, not a runtime trace.</span></div></div>}

function QueueSim(){const [prediction,setPrediction]=useState<string[]>([]);const [revealed,setRevealed]=useState(false);const pending=['A3','B1','Premium1'];const answer=['Premium1','B1','A3'];const add=(j:string)=>!prediction.includes(j)&&prediction.length<pending.length&&setPrediction([...prediction,j]);return <div className="panel sim-panel"><div className="panel-head"><div><div className="eyebrow">THREE GLOBAL SLOTS · TWO PER USER</div><h2>Predict the next job</h2><p className="muted">A1 and A2 are running. A3 is at the per-user cap; B1 and Premium1 are waiting.</p></div><Badge>[C] policy-inspired simplification</Badge></div><div className="slot-row">{['A1 · RUNNING','A2 · RUNNING','OPEN SLOT'].map(x=><div className={x==='OPEN SLOT'?'slot-empty':'slot-live'} key={x}>{x}</div>)}</div><div className="prediction-options">{pending.map(j=><button key={j} className={prediction.includes(j)?'chosen':''} disabled={revealed} onClick={()=>add(j)}>{j}{j==='A3'?' · user A at limit':j==='Premium1'?' · priority':''}</button>)}</div><div className="prediction-row"><span>Your predicted order: {prediction.length?prediction.join(' → '):'choose a job order above'}</span><button className="button green-button" disabled={prediction.length!==3} onClick={()=>setRevealed(true)}>Reveal scheduler order</button></div>{revealed&&<div className="queue-reveal"><div className="queue-steps">{answer.map((j,i)=><div key={j}><i>{i+1}</i><b>{j}</b><small>{j==='A3'?'User A now has a free permit':j==='Premium1'?'Priority rank moves it ahead':'Eligible user gets the next slot'}</small></div>)}</div><p>The real queue uses priority rank then ticket order, and chooses the first owner under their cap. This scenario simplifies arrival timing to highlight eligibility and priority. Check bot/services/dl_queue.py for exact behavior.</p></div>}</div>}

function UploadSim(){const [slots,setSlots]=useState(2);const [budget,setBudget]=useState(100);const [files,setFiles]=useState([49,40,20]);const admitted=(()=>{let used=0,n=0;for(const size of files){const cost=Math.min(size,budget);if(n<slots&&used+cost<=budget){n++;used+=cost}}return {n,used}})();return <div className="panel sim-panel"><div className="panel-head"><div><div className="eyebrow">SLOT + BYTE RESERVATION</div><h2>UploadGate</h2><p className="muted">Edit file sizes and limits. This is a simplified fit check; the real gate is strict FIFO.</p></div><Badge>[C] defaults: 2 slots · 100 MiB</Badge></div><div className="slider-grid"><Slider label="Concurrent slots" value={slots} min={1} max={4} onChange={setSlots} unit=""/><Slider label="Byte budget" value={budget} min={30} max={150} onChange={setBudget} unit=" MiB"/></div><div className="file-bars">{files.map((f,i)=><label key={i}>File {i+1}<input type="range" min="5" max="100" value={f} onChange={e=>setFiles(files.map((x,j)=>j===i?Number(e.target.value):x))}/><b>{f} MiB</b></label>)}</div><div className="gate-result"><b>{admitted.n} / {files.length} files admitted now</b><span>{admitted.used} / {budget} MiB reserved</span><div className="progress-track"><i style={{width:`${Math.min(100,admitted.used/budget*100)}%`}}/></div></div><p className="muted">The actual gate prevents later small files overtaking the head waiter. A file larger than the whole budget consumes the full budget and can run alone.</p></div>}

function Slider({label,value,min,max,onChange,unit}:{label:string;value:number;min:number;max:number;onChange:(n:number)=>void;unit:string}){return <label className="slider-control"><span>{label}<b>{value}{unit}</b></span><input type="range" min={min} max={max} value={value} onChange={e=>onChange(Number(e.target.value))}/></label>}

function MemorySim(){const [anon,setAnon]=useState(430);const [cache,setCache]=useState(180);const [other,setOther]=useState(250);const [swap,setSwap]=useState(0);const total=952,approx=Math.max(0,total-anon-cache*.25-other);const pressure=approx<100?'High conceptual pressure':approx<220?'Watch reclaim and activity':'Headroom in this simplified model';return <div className="panel sim-panel"><div className="panel-head"><div><div className="eyebrow">VM MEMORY MODEL</div><h2>Where did the memory go?</h2><p className="muted">Host snapshot: about 952 MiB RAM and 2 GiB swap. Adjust conceptual categories below.</p></div><Badge>[E] simplified, not Linux MemAvailable</Badge></div><div className="memory-stacked"><i style={{width:`${anon/total*100}%`}} className="anon"/><i style={{width:`${cache/total*100}%`}} className="cache"/><i style={{width:`${other/total*100}%`}} className="other"/><i style={{width:`${approx/total*100}%`}} className="free"/></div><div className="memory-legend"><span><i className="anon"/>Anonymous {anon} MiB</span><span><i className="cache"/>Page cache {cache} MiB</span><span><i className="other"/>Other {other} MiB</span><span><i className="free"/>Rough residual {approx} MiB</span></div><div className="slider-grid"><Slider label="Anonymous / resident app memory" value={anon} min={100} max={700} onChange={setAnon} unit=" MiB"/><Slider label="Page cache (partly reclaimable)" value={cache} min={0} max={400} onChange={setCache} unit=" MiB"/><Slider label="Other host/cgroup memory" value={other} min={100} max={600} onChange={setOther} unit=" MiB"/><Slider label="Swap occupied" value={swap} min={0} max={2048} onChange={setSwap} unit=" MiB"/></div><div className={`pressure-callout ${approx<100?'warn':''}`}><b>{pressure}</b><span>{swap>0?'Swap occupancy alone is not proof of active thrashing. Check swap-in/out rate, memory PSI and latency.':'Combine available memory with active swap and PSI; no single number is the whole story.'}</span></div><div className="callout"><b>Academic connection</b><span>A page fault is the virtual-memory mechanism from OS. A major fault needs storage I/O; page cache may be reclaimed, while anonymous pages may be swapped. The model simplifies Linux accounting, reclaim and shared pages.</span></div></div>}

function PercentileSim(){const [tail,setTail]=useState(3);const vals=[1.2,1.4,1.5,1.5,1.7,1.8,1.9,2.1,2.3,2.5,2.7,2.8,3.1,3.4,3.7,4.1,4.8,5.2,6.1,8,12,18,24,34,...Array(tail).fill(45)];return <div className="panel sim-panel"><div className="panel-head"><div><div className="eyebrow">LATENCY DISTRIBUTION</div><h2>Mean vs tail</h2><p className="muted">Add slow observations to see how the mean and percentiles respond.</p></div><Badge>[E] illustrative samples</Badge></div><Slider label="Additional slow observations" value={tail} min={0} max={20} onChange={setTail} unit=""/><div className="percentile-cards">{[['Mean',vals.reduce((a,b)=>a+b,0)/vals.length],['p50',percentile(vals,.5)],['p90',percentile(vals,.9)],['p95',percentile(vals,.95)],['p99',percentile(vals,.99)]].map(([n,v])=><div key={String(n)}><small>{n}</small><b>{Number(v).toFixed(1)}s</b></div>)}</div><div className="bar-chart">{vals.map((v,i)=><i key={i} title={`${v}s`} style={{height:`${Math.max(5,Number(v)/45*100)}%`}} className={v>=34?'tail-bar':''}/>)}</div><p className="muted">The source project reports warm-up timing percentiles separately from user-job samples. A small sample makes p99 unstable; these generated values are not project measurements.</p></div>}

function LittleLawSim(){const [rate,setRate]=useState(3);const [time,setTime]=useState(10);const [workers,setWorkers]=useState(3);return <div className="panel sim-panel"><div className="panel-head"><div><div className="eyebrow">QUEUEING THEORY · L = λW</div><h2>Little’s Law, in motion</h2><p className="muted">Use jobs/minute and minutes in system. Stable long-run average only.</p></div><Badge>[E] teaching example</Badge></div><div className="slider-grid"><Slider label="Arrivals λ" value={rate} min={1} max={20} onChange={setRate} unit=" jobs/min"/><Slider label="Time in system W" value={time} min={1} max={30} onChange={setTime} unit=" min"/><Slider label="Worker slots (context only)" value={workers} min={1} max={10} onChange={setWorkers} unit=""/></div><div className="law-equation"><span>L</span><i>=</i><b>{rate}</b><i>×</i><b>{time}</b><i>=</i><strong>{littleLaw(rate,time)}<small>average jobs in system</small></strong></div><div className="queue-visual">{Array.from({length:Math.min(30,Math.round(littleLaw(rate,time)))},(_,i)=><i key={i} className={i<workers?'worker-job':''}/>)}</div><div className="callout"><b>Why daily average misleads</b><span>1,000 jobs/day spread evenly is about 0.69 jobs/minute. 100 jobs arriving in 10 minutes is 10 jobs/minute—a different burst. [E] These are examples, not this bot’s measured traffic.</span></div></div>}

function CapacitySim(){const [day,setDay]=useState(100);const [burst,setBurst]=useState(12);const [size,setSize]=useState(25);const [dl,setDl]=useState(120);const [up,setUp]=useState(90);const [slots,setSlots]=useState(3);const avgMbps=mbps(size*day,86400);const burstMbps=mbps(size*burst,600);const gb=gigabytesPerDay(day,size);const active=burst*(dl+up)/600;return <div className="panel sim-panel"><div className="panel-head"><div><div className="eyebrow">CAPACITY ESTIMATOR</div><h2>Estimate each resource</h2><p className="muted">Set an assumed workload. Outputs are [E], not a production forecast.</p></div><Badge>Not measured: actual jobs/day and file sizes</Badge></div><div className="slider-grid"><Slider label="Jobs per day" value={day} min={1} max={5000} onChange={setDay} unit=""/><Slider label="Burst jobs in 10 minutes" value={burst} min={1} max={500} onChange={setBurst} unit=""/><Slider label="Average media size" value={size} min={1} max={49} onChange={setSize} unit=" MB"/><Slider label="Download time per job" value={dl} min={10} max={900} onChange={setDl} unit=" s"/><Slider label="Upload time per job" value={up} min={10} max={900} onChange={setUp} unit=" s"/><Slider label="Download worker slots" value={slots} min={1} max={20} onChange={setSlots} unit=""/></div><div className="estimate-grid"><div><small>AVERAGE INGRESS</small><b>{avgMbps.toFixed(2)} Mbps</b><span>jobs/day × MB × 8 / day</span></div><div><small>AVERAGE EGRESS</small><b>{avgMbps.toFixed(2)} Mbps</b><span>assumes same media size uploaded</span></div><div><small>TOTAL MEDIA / DAY</small><b>{gb.toFixed(1)} GB</b><span>before retries/protocol overhead</span></div><div><small>BURST INGRESS</small><b>{burstMbps.toFixed(1)} Mbps</b><span>burst jobs × MB × 8 / 600s</span></div><div><small>ARRIVAL WORK (L≈λW)</small><b>{active.toFixed(1)} jobs</b><span>burst rate × download+upload time</span></div><div><small>TEMP FILES</small><b>Up to ~{Math.min(burst,Math.ceil(burst*dl/600),slots*10)*size} MB (rough)</b><span>real overlap depends on stage lifecycle</span></div></div><p className="muted">This assumes uniform sizes and durations. Real capacity planning uses distributions, separates download/upload legs, includes retry overhead and measures temporary-file overlap.</p></div>}

function BottleneckSim(){const [answer,setAnswer]=useState<string|null>(null);const [scenario,setScenario]=useState(0);const cases=[{s:'CPU busy is low, steal is high, and all jobs slow at once.',a:'CPU steal / virtualization wait',why:'Guest processes may be runnable but the hypervisor schedules other guests. Adding processes cannot reclaim stolen time.'},{s:'Downloads finish but queue of completed files grows; upload slots stay full.',a:'Telegram upload capacity',why:'The downstream send stage is constrained; additional download concurrency could grow disk backlog.'},{s:'Available memory falls, swap-in spikes, memory PSI rises during concurrent sends.',a:'Memory pressure during upload overlap',why:'Correlate active paging and PSI; inspect streaming path, upload concurrency and cgroup limits.'},{s:'Only one URL is slow for all callers; metadata pool is full of identical extraction.',a:'Duplicate metadata work / missing coalescing',why:'Single-flight should make concurrent identical requests share one extraction.'}];const c=cases[scenario];return <div className="panel sim-panel"><div className="eyebrow">DIAGNOSIS PRACTICE · {scenario+1}/{cases.length}</div><h2>Which resource is probably limiting?</h2><div className="symptom-card">“{c.s}”</div><div className="bottleneck-options">{['CPU saturation','CPU steal','RAM / memory pressure','Disk throughput','Network / external API','Queue policy','Telegram upload','Duplicate work'].map(x=><button className={answer===x?'chosen':''} onClick={()=>setAnswer(x)} key={x}>{x}</button>)}</div>{answer&&<div className="quiz-feedback"><b>{answer===c.a?'Good diagnosis.':`Consider: ${c.a}.`}</b> {c.why}<button onClick={()=>{setScenario((scenario+1)%cases.length);setAnswer(null)}}>Next symptom →</button></div>}</div>}

function ScaleSim(){const [level,setLevel]=useState(1);const [choice,setChoice]=useState('');const s=scaling[level];const options=['Increase VM size','Increase concurrency','PostgreSQL','Redis / durable queue','More worker processes','Object storage','Multiple nodes','Kubernetes'];return <div className="panel sim-panel"><div className="panel-head"><div><div className="eyebrow">CHOOSE FIRST · THEN REVEAL</div><h2>What changes at scale?</h2><p className="muted">A multiplier is a thought experiment, not evidence of a bottleneck.</p></div><Badge>{s.title}</Badge></div><div className="scale-slider">{scaling.map((x,i)=><button className={level===i?'on':''} key={x.multiplier} onClick={()=>{setLevel(i);setChoice('')}}>{x.multiplier.toLocaleString()}×</button>)}</div><div className="symptom-card">What do you think breaks first? Choose one option.</div><div className="bottleneck-options">{options.map(x=><button className={choice===x?'chosen':''} onClick={()=>setChoice(x)} key={x}>{x}</button>)}</div>{choice&&<div className="scale-reveal"><div className="eyebrow">REVEAL · {s.title.toUpperCase()}</div><p><b>What might break:</b> {s.breaks}</p><p><b>Measure:</b> {s.metric}</p><p><b>Reasonable next change:</b> {s.change}</p><p className="muted">Your choice: {choice}. It becomes justified only if evidence points to its specific problem.</p></div>}</div>}

function RebuildBoss() {
  const [mode, setMode] = useState<'rebuild' | '100k'>('rebuild');
  const [choices, setChoices] = useState<Record<string, string>>({});
  const [reveal, setReveal] = useState(false);
  const decisions: [string, string[]][] = [
    ['Ingress', ['Long polling', 'Webhook']], ['Handler model', ['Synchronous', 'Asyncio']],
    ['Blocking work', ['Same event loop', 'Threads', 'Processes']],
    ['Scheduling', ['Start immediately', 'Fair in-memory queue', 'Durable distributed queue']],
    ['Admission', ['No limits', 'Concurrency + rate limits']],
    ['Metadata', ['Extract every request', 'Cache only', 'Cache + single-flight']],
    ['Upload', ['Buffer full file', 'Stream from disk']],
    ['State', ['JSON only', 'SQLite for history + local JSON']],
    ['Cancellation', ['Ignore cancellation', 'Cooperative checks']],
    ['Retries', ['Retry every error', 'Classify transient/permanent + bounded retries']],
    ['Health', ['Process active only', 'Heartbeat + dependency/disk checks']],
    ['Deployment', ['Interactive shell', 'systemd/cgroups']],
    ['Scale', ['Add Kafka first', 'Measure bottleneck, then evolve']],
  ];
  const real: Record<string, string> = {
    Ingress: 'Long polling', 'Handler model': 'Asyncio', 'Blocking work': 'Threads',
    Scheduling: 'Fair in-memory queue', Admission: 'Concurrency + rate limits',
    Metadata: 'Cache + single-flight', Upload: 'Stream from disk',
    State: 'SQLite for history + local JSON', Cancellation: 'Cooperative checks',
    Retries: 'Classify transient/permanent + bounded retries',
    Health: 'Heartbeat + dependency/disk checks', Deployment: 'systemd/cgroups',
    Scale: 'Measure bottleneck, then evolve',
  };
  return <>
    <SectionTitle eyebrow="FINAL BOSS · REQUIREMENTS BEFORE ANSWERS" title="Rebuild the downloader" description="Design from first principles. There is no single correct architecture; make your reasoning visible before comparing options." />
    <div className="tabbar">
      <button className={mode === 'rebuild' ? 'selected' : ''} onClick={() => { setMode('rebuild'); setReveal(false); }}>Rebuild current project</button>
      <button className={mode === '100k' ? 'selected' : ''} onClick={() => { setMode('100k'); setReveal(false); }}>System design · 100k jobs/day</button>
    </div>
    {mode === '100k' ? <SystemDesignMode /> : <div>
      <div className="boss-requirements">
        <div className="eyebrow">REQUIREMENTS</div><h2>Design a service that:</h2>
        <ul>
          <li>Accepts media links from Telegram users and lets them choose a supported format.</li>
          <li>Downloads and processes media, then returns the result to the requesting Telegram chat.</li>
          <li>Runs on a small, single VM at first, with unknown burst size and media distribution.</li>
          <li>Has a final upload-size cap below the Bot API ceiling.</li>
          <li>Should remain responsive during network waits and bound resource usage.</li>
          <li>Must explain behavior if a process restarts during an active job.</li>
        </ul>
        <p>No job/day or peak concurrency is provided; state assumptions or ask for measurements.</p>
      </div>
      <div className="panel boss-panel">
        <div className="panel-head"><div><div className="eyebrow">MAKE THE DESIGN</div><h2>Choose one for each boundary</h2></div><span>{Object.keys(choices).length}/{decisions.length} selected</span></div>
        {decisions.map(([name, opts]) => <div className="decision-row" key={name}><b>{name}</b><div>{opts.map(option => <button key={option} className={choices[name] === option ? 'chosen' : ''} onClick={() => setChoices({ ...choices, [name]: option })}>{option}</button>)}</div></div>)}
        <button className="button green-button" disabled={Object.keys(choices).length < decisions.length} onClick={() => setReveal(true)}>Compare with the shipped v1 →</button>
        {reveal && <div className="boss-reveal">
          <h3>One reasonable shipped design</h3>
          <p>v1 uses long polling, PTB/asyncio, blocking work in bounded thread pools, a fair in-memory queue, local rate limits, metadata cache + single-flight, file-backed streaming + UploadGate, SQLite WAL history, cooperative cancellation, bounded classified retries, heartbeat/health checks, and systemd/cgroups.</p>
          {decisions.map(([name]) => <div key={name} className={choices[name] === real[name] ? 'compare-match' : 'compare-diff'}><b>{name}</b><span>Your choice: {choices[name]}</span><span>v1: {real[name]}</span><small>{choices[name] === real[name] ? 'Same as v1; alternatives may still be valid.' : 'Different from v1; discuss the requirement and trade-off behind your choice.'}</small></div>)}
          <div className="callout"><b>Not the only right design</b><span>Webhook ingress, durable work state or multiple workers could be right under different requirements. First measure the workload, define recovery semantics and identify the constraint.</span></div>
        </div>}
      </div>
    </div>}
  </>;
}

function SystemDesignMode(){
  const prompts=[['Requirements','Define job completion, supported media, latency, failure recovery, delivery semantics and availability goals.'],['Estimation','Estimate average/burst arrival, bytes per job, network Mbps, worker concurrency and temporary disk. State assumptions.'],['API','Choose Telegram polling or webhook and describe update acknowledgement, deduplication and user status.'],['Data','Separate job state, history, cache, temporary media and secrets. Which state must survive a restart?'],['Queueing','Choose admission, fairness, priority, bounded backlog and worker ownership.'],['Processing','Place metadata, download, Deno/FFmpeg, temporary storage and upload into measurable stages.'],['Failure','Explain retries, cancellation, timeouts, ambiguous Telegram outcomes and idempotency.'],['Scaling','Describe how to evolve from one node; name the measured trigger for each added component.']];
  const [notes,setNotes]=useState<Record<string,string>>({});const [shown,setShown]=useState(false);const complete=prompts.filter(([k])=>notes[k]?.trim()).length;
  return <><div className="boss-requirements"><div className="eyebrow">INTERVIEW PROMPT · REQUIREMENTS ONLY</div><h2>Design a Telegram media-downloader service for 100,000 jobs/day.</h2><ul><li>Users submit URLs in Telegram and receive downloadable media in the same chat.</li><li>Media sources and Telegram are external dependencies with variable response time and quotas.</li><li>Job size distribution, burst rate, latency target, availability target and retry semantics are unspecified: ask clarifying questions or state explicit assumptions.</li><li>Design should preserve fairness, protect temporary storage and explain duplicate/lost work on failure.</li></ul><p>Estimate average arrival rate and burst separately. State assumptions; the prompt does not provide enough data for exact capacity sizing.</p></div><div className="design-workbench"><div className="eyebrow">YOUR DESIGN NOTES · {complete}/{prompts.length} SECTIONS STARTED</div>{prompts.map(([title,question])=><label className="design-prompt" key={title}><span>{title}</span><b>{question}</b><textarea value={notes[title]||''} onChange={e=>setNotes({...notes,[title]:e.target.value})} placeholder={`Write your ${title.toLowerCase()} reasoning…`}/></label>)}<button className="button green-button" disabled={complete<prompts.length} onClick={()=>setShown(true)}>Compare with one reasonable design →</button></div>{shown&&<div className="panel boss-reveal"><div className="eyebrow">ONE REASONABLE DESIGN · ASSUMPTIONS EXPLICIT</div><h2>Scale the boundaries that need it</h2><p>Assume restart recovery and multi-worker throughput are required; the prompt does not provide a burst rate, mean file size or SLO, so exact worker count, bandwidth and storage are not calculated. Start with a webhook or dedicated Telegram ingress, validate/rate-limit and persist an idempotent job record, then place admitted work on a durable queue. Workers claim jobs with leases, download into object storage or bounded shared staging, process via isolated yt-dlp/FFmpeg workers, and send through a separately limited upload stage. Persist outcomes and reconcile ambiguous delivery when Telegram capabilities permit.</p><div className="diagnosis-grid"><div><small>Estimation next</small><p>100,000/86,400 ≈ 1.16 jobs/second average [E]. Jobs/day gives only average λ. Ask for burst jobs/min, MB/job, download/upload durations and retry rate; use L=λW as a stable-average check, then model bursts and stage concurrency separately.</p></div><div><small>Data choice</small><p>Relational job state is useful for ownership/status and transactions; object storage holds large files; cache is for derived/reusable data. Select PostgreSQL or a managed equivalent if multiple workers need shared durable state.</p></div><div><small>Reliability</small><p>At-least-once queue delivery plus idempotent state transitions and worker leases is a common trade-off. External upload can remain ambiguous without an API idempotency mechanism.</p></div><div><small>Compared with v1</small><p>v1 is one host process with in-memory queue and local SQLite; it is not resumable durable execution. The prompt’s scale alone does not prove several machines are needed; burst, SLO, recovery and quota requirements decide.</p></div></div><div className="callout"><b>Trade-off</b><span>A durable queue, shared database and object storage add network failure, leases, duplicate execution, monitoring and operational cost. Validate that a larger single node or bounded worker change cannot satisfy measured requirements first.</span></div></div>}</>;
}

function Portfolio(){const [audience,setAudience]=useState('SDE interviewer');const [duration,setDuration]=useState('2 minutes');const scripts:Record<string,Record<string,string>>={
 'Recruiter':{'30 seconds':'I built and operate a Telegram media-downloader bot. I focused on keeping a small production VM responsive and safe by bounding concurrency, streaming uploads and measuring behavior before adding infrastructure.','2 minutes':'This is a self-hosted Telegram bot using PTB/asyncio to guide media requests, yt-dlp for downloads, and FFmpeg where needed. I added a fair download queue and per-user limits, metadata single-flight, UploadGate and streamed file uploads. History is in local SQLite WAL; production uses systemd/cgroups with Kuma health monitoring. The production-stable app is v1.0.0. I am careful not to claim scale the measurements did not show.','5 minutes':'Start with a single-node backend that accepts Telegram links, extracts metadata, queues downloads, writes to temporary disk, streams media to Telegram, and records history. The most interesting engineering work was aligning concurrency with a constrained VM: blocking extraction moved off the event loop, identical metadata requests coalesce, downloads are admitted fairly, and uploads have separate slot/byte limits and stream from disk. SQLite stores durable history, but job execution is not resumable. Tests cover the actual failure paths. A 24-hour comparison showed lower average swap activity and better warm-up tails, but CPU steal changed and user job sample was small, so I describe it as correlated evidence, not causal proof. The lesson was to measure first and keep architecture simple until a requirement appears.','15 minutes':'Walk through request lifecycle, event-loop boundaries, metadata cache vs in-flight coalescing, fair queue and per-user caps, thread pools vs process pools, disk staging and streamed upload, UploadGate, SQLite WAL vs volatile job state, timeout/cancellation ambiguity, cgroup/systemd limits, health checks, experiments/confounders, and what would trigger a durable distributed queue. Emphasize code/test evidence, historical measurement limits and no unsupported scale claim.'},
 'SDE interviewer':{'30 seconds':'A single-node async Telegram backend uses bounded threads for blocking yt-dlp, a fair queue for download admission, and a byte-aware gate plus streaming for uploads. I optimized based on resource constraints and kept durable history separate from volatile job execution.','2 minutes':'The bot receives Telegram updates via PTB. Async handlers validate inputs and rate-limit users, metadata is cached and coalesced, then jobs enter an in-memory fair queue with global/per-user limits. Blocking yt-dlp runs in a thread pool and can invoke FFmpeg/Deno subprocesses. Files stage on temporary disk. UploadGate reserves slot and byte budget, and PTB streams the open file handle. SQLite WAL stores history, but the queue/jobs are not resumable after restart. I chose threads because extraction/download are largely I/O or subprocess work and no GIL-bound Python bottleneck was measured.','5 minutes':'[C] Outline each boundary and capacity guard; discuss cache vs single-flight and fairness. [C] Explain BadRequest inheritance-order regression corrected in commit 830f351 and focused passing tests. [M] The 24-hour report’s host-level swap-in/out and PSI fell, but CPU steal also changed and user-job sample size was too small for a user-latency claim. [R] I would instrument queue wait, phase duration and per-job resources before changing concurrency.','15 minutes':'Use requirements and workload first, draw the request path, make queue and persistence semantics explicit, estimate bytes/time, identify failure and retry semantics, then propose staged scaling triggers. Defend why no Redis/Celery/process pool and what evidence would change that choice.'},
 'DevOps / SRE':{'30 seconds':'The bot is one systemd-managed process with cgroup resource caps, local heartbeat/health checks and Kuma. I treat process liveness, dependency health and successful user jobs as different signals.','2 minutes':'Production is a small Oracle VM with shared CPU, constrained RAM and swap. systemd supervises the bot and cgroups bound memory/CPU/tasks; Kuma and bgutil are container side services; WARP is optional host egress. A health daemon combines unit status, 30-second heartbeat, polling/dependency checks and disk. Rollouts verify a fresh heartbeat and logs. Historical metrics are timestamped; old cumulative counters are not current rates.','5 minutes':'Discuss blast radius, controlled service restart, cgroup events/PSI/swap/steal, sidecar pressure, readiness/liveness limits, timeout/cancellation, rollback, and evidence labels. The health endpoint can be green while an upload path fails. A historical 24-hour comparison had confounders and is not an SLO proof.','15 minutes':'Define user-job SLI and target, instrument phase latency and success by dependency, measure queue delay and cgroup pressure, specify alerts/runbook/rollback, and design a one-variable experiment. Explain current job loss on restart and how a durability objective would change architecture.'},
 'System-design interviewer':{'30 seconds':'I start from job semantics and workload, then bounded single-node processing fits the known constraints. I would not distribute until recovery, throughput or availability requirements exceed a measured one-node capacity.','2 minutes':'Clarify accepted sources, media/file size, burst rate, latency, job recovery, duplicate delivery and availability. Separate ingress, metadata, download, temporary storage and upload capacity. Start with an async bot, bounded workers, per-user fairness, local history and idempotency caveats. Measure which stage saturates before adding broker or nodes.','5 minutes':'Estimate jobs×bytes/time, compute burst arrival/service relationship with Little’s Law, bound RAM/disk by concurrent stage overlap, set timeouts and retry semantics, and specify queue durability. Identify Telegram/source quotas and ambiguous upload outcome.','15 minutes':'Explore vertical scaling, cautious worker increase, durable broker, shared DB/object storage and multiple nodes as triggered steps. For each, state new consistency, ownership, rate-limit, duplicate-execution and partition behavior; tie adoption to SLO and measured bottleneck.'},
 'Client':{'30 seconds':'It is a Telegram bot that downloads supported public media and returns it in chat, with guarded resource use and clear failure handling.','2 minutes':'A user sends a link, chooses a media format and receives the result. The service limits concurrent work, streams files instead of keeping full uploads in memory, and stores local history. Availability depends on Telegram and the source site.','5 minutes':'Explain source/site limitations, max file size, expected workflow, privacy of local state and what happens when a job is interrupted. Do not promise exact delivery or unsupported sources.','15 minutes':'Discuss functional scope, supported integrations, limits, operational support expectations, measured reliability data and future requirements before estimating schedule or scaling changes.'}};
  return <><SectionTitle eyebrow="PORTFOLIO & COMMUNICATION" title="Tell the engineering story" description="Adjust depth to the audience. Keep the factual core constant; do not exaggerate traffic or causal impact."/><div className="portfolio-controls"><label>Audience<select value={audience} onChange={e=>setAudience(e.target.value)}>{Object.keys(scripts).map(x=><option key={x}>{x}</option>)}</select></label><label>Length<select value={duration} onChange={e=>setDuration(e.target.value)}>{['30 seconds','2 minutes','5 minutes','15 minutes'].map(x=><option key={x}>{x}</option>)}</select></label></div><article className="portfolio-script"><div className="eyebrow">{audience.toUpperCase()} · {duration.toUpperCase()}</div><p>{scripts[audience][duration]}</p><div className="portfolio-points"><span><Badge>[C]</Badge> code/test facts</span><span><Badge>[M]</Badge> historical metrics</span><span><Badge>[R]</Badge> future triggers</span></div></article><div className="talk-track-grid">{['Why','Alternatives','Evidence','Trade-offs','Production verification','Scaling trigger'].map((x,i)=><div key={x}><span>0{i+1}</span><b>{x}</b><p>{['What user or resource problem did this solve?','What else could you choose and why not?','Which claim is measured versus code-derived?','What cost or limitation remains?','What test and live signal prove it works?','What measurable condition changes the architecture?'][i]}</p></div>)}</div><div className="callout"><b>Honest evidence</b><span>The 374acfd commit froze documentation; it did not change the application. Describe the application from v1.0.0 / 830f351.</span></div></>;
}
